import { test, expect } from '@playwright/test';

test.describe('Virtual Scroll List Performance with 10,000 Rows', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/virtual-scroll-list');
  });

  test('should handle 10,000 rows without lag', async ({ page }) => {
    // Setup: intercept the API call to get the list data
    await page.route('**/api/list-data', (route) => {
      route.continue();
    });

    // Get the list container
    const listContainer = page.getByRole('region', { name: /virtual scroll list/i });
    await expect(listContainer).toBeVisible();

    // Get the scrollbar
    const scrollbar = page.getByRole('slider', { name: /scroll/i });
    await expect(scrollbar).toBeVisible();

    // Get the first item
    const firstItem = page.getByRole('heading', { name: /item 1/i });
    await expect(firstItem).toBeVisible();

    // Get the last item
    const lastItem = page.getByRole('heading', { name: /item 10000/i });
    await expect(lastItem).toBeVisible();

    // Verify the list has 10,000 items
    const itemCount = page.getByRole('heading', { name: /item \d+/i }).count();
    expect(itemCount).toBe(10000);

    // Verify the scrollbar is visible and has a value
    await expect(scrollbar).toBeVisible();
    const scrollValue = await scrollbar.evaluate((el) => el.value);
    expect(scrollValue).toBeGreaterThan(0);

    // Verify the list is not empty
    const listItems = page.getByRole('listitem');
    await expect(listItems).toHaveCount(10000);

    // Verify the list is not empty
    const listItemCount = page.getByRole('listitem').count();
    expect(listItemCount).toBe(10000);

    // Verify the first item is visible
    await expect(firstItem).toBeVisible();

    // Verify the last item is visible
    await expect(lastItem).toBeVisible();

    // Verify the list is responsive and does not cause layout shift
    await expect(page).toHaveNoCrashed();
  });

  test('should handle dynamic updates to the list without lag', async ({ page }) => {
    // Setup: intercept the API call to get the list data
    await page.route('**/api/list-data', (route) => {
      route.continue();
    });

    // Get the list container
    const listContainer = page.getByRole('region', { name: /virtual scroll list/i });
    await expect(listContainer).toBeVisible();

    // Get the scrollbar
    const scrollbar = page.getByRole('slider', { name: /scroll/i });
    await expect(scrollbar).toBeVisible();

    // Get the first item
    const firstItem = page.getByRole('heading', { name: /item 1/i });
    await expect(firstItem).toBeVisible();

    // Get the last item
    const lastItem = page.getByRole('heading', { name: /item 10000/i });
    await expect(lastItem).toBeVisible();

    // Verify the list has 10,000 items
    const itemCount = page.getByRole('heading', { name: /item \d+/i }).count();
    expect(itemCount).toBe(10000);

    // Verify the scrollbar is visible and has a value
    await expect(scrollbar).toBeVisible();
    const scrollValue = await scrollbar.evaluate((el) => el.value);
    expect(scrollValue).toBeGreaterThan(0);

    // Verify the list is responsive and does not cause layout shift
    await expect(page).toHaveNoCrashed();

    // Trigger a dynamic update to the list
    await page.route('**/api/list-data', (route) => {
      route.continue();
    });

    // Verify the list updates without lag
    const updatedItemCount = page.getByRole('heading', { name: /item \d+/i }).count();
    expect(updatedItemCount).toBe(10000);

    // Verify the scrollbar value remains consistent
    const updatedScrollValue = await scrollbar.evaluate((el) => el.value);
    expect(updatedScrollValue).toBeGreaterThan(0);

    // Verify the list is still responsive and does not cause layout shift
    await expect(page).toHaveNoCrashed();
  });
});
